%% pidtune_compare.m  —  MATLAB's built-in PID tuning on the identified rig model.
% Generated by the Python pipeline from plant_params.json (farthest sensor, ch1).
% Plant per supply voltage: G(s) = K e^(-theta s) / (tau s + 1),  input = PWM %, output = degC.
% Run in MATLAB (Control System Toolbox). Paste the 4 V gains into BASELINE_OVERRIDES in evaluate.py.

%      V      K[degC/%]   tau[s]  theta[s]
P = [
    2.0  0.08620  1079.9  40.0
    3.0  0.18284  1018.1  40.0
    4.0  0.30307  949.2  40.0
    5.0  0.43929  880.5  40.0
];

fprintf('%5s %10s %10s %10s   | %s
', 'V', 'Kp', 'Ki', 'Kd', 'step info with gains tuned at 4 V');
G4 = tf(P(3,2), [P(3,3) 1], 'InputDelay', P(3,4));
C4 = pidtune(G4, 'PID');                     % MATLAB default: balance robustness/performance
for i = 1:size(P,1)
    G = tf(P(i,2), [P(i,3) 1], 'InputDelay', P(i,4));
    C = pidtune(G, 'PID');
    S = stepinfo(feedback(C4*G, 1));         % 4 V gains on this voltage's plant (no saturation in linear sim)
    fprintf('%5.1f %10.3f %10.5f %10.2f   | overshoot %5.1f %%, settling %6.0f s
', ...
            P(i,1), C.Kp, C.Ki, C.Kd, S.Overshoot, S.SettlingTime);
end
fprintf('
Gains tuned at 4 V (paste into evaluate.py):
  {"Kp": %.3f, "Ki": %.5f, "Kd": %.2f}
', C4.Kp, C4.Ki, C4.Kd);

% Ziegler-Nichols open-loop on the same 4 V model, for reference
K = P(3,2); tau = P(3,3); th = P(3,4);
fprintf('ZN (open loop) at 4 V: Kp=%.3f Ki=%.5f Kd=%.2f
', 1.2*tau/(K*th), 1.2*tau/(K*th)/(2*th), 1.2*tau/(K*th)*0.5*th);
